import { randomUUID } from 'node:crypto';
import { z } from 'zod';
import { definition, type CanvasEvent, type GameKind, type GameSettings, type GameSeat, type GameSummary, type GameView } from '../../../../packages/contracts/src/games';
import type { Service } from '../service';
import type { Connection } from '../db';
import { fail } from '../security';
import { act, depart, project, startEngine, timeout } from './engine';
import { pokerJoin } from './poker';
import type { Engine } from './common';
const kinds=['poker','domino','telephone','drawing','words','ludo','four'] as const;
const settingsSchema=z.object({maxPlayers:z.number().int().min(2).max(8),seconds:z.union([z.literal(45),z.literal(60),z.literal(90)]).default(60),rounds:z.number().int().min(1).max(3).default(1),language:z.enum(['en','fa']).default('en'),domino:z.enum(['draw','block']).default('draw'),chips:z.union([z.literal(1000),z.literal(2000)]).default(1000),blind:z.union([z.literal(10),z.literal(20),z.literal(50)]).default(20)}).strict();
export const gameCreate=z.object({requestId:z.string().uuid(),channelId:z.string().min(1).max(100),kind:z.enum(kinds),settings:settingsSchema}).strict().refine(b=>b.settings.maxPlayers>=definition(b.kind).min&&b.settings.maxPlayers<=definition(b.kind).max,'Choose a valid player limit.');
const action=z.object({type:z.enum(['drop','tile','draw','pass','next','roll','token','fold','check','call','raise','stroke','clear','guess','submit','clue','word']),token:z.string().max(40).optional(),piece:z.number().int().min(0).max(3).optional(),column:z.number().int().min(0).max(6).optional(),tile:z.number().int().min(0).max(27).optional(),end:z.enum(['left','right']).optional(),to:z.number().int().min(0).max(1000000).optional(),index:z.number().int().min(0).max(24).optional(),count:z.number().int().min(1).max(9).optional(),text:z.string().max(180).optional(),stroke:z.object({color:z.string().max(7),width:z.number().int(),points:z.array(z.tuple([z.number().int().min(0).max(1000),z.number().int().min(0).max(1000)])).min(1).max(100)}).strict().optional()}).strict();
export const gameCommand=z.object({requestId:z.string().uuid(),revision:z.number().int().positive(),kind:z.enum(['join','start','leave','close','action']),action:action.optional()}).strict();
export type Session={id:string;serverId:string;channelId:string;kind:GameKind;hostId:string;hostName:string;settings:GameSettings;seats:GameSeat[];status:'waiting'|'playing'|'finished';revision:number;createdAt:number;updatedAt:number;pausedUntil:number;pauseStarted:number;result:string|null;state:Engine|null};
const activeSeats=(g:Session)=>g.seats.filter(s=>!s.left);
export async function arcadeBusy(tx:Connection,uid:string,except='') {return Boolean(await tx.one("SELECT p.user_id FROM game_players p JOIN game_sessions g ON g.id=p.game_id WHERE p.user_id=? AND g.status<>'finished' AND g.id<>?",[uid,except]));}
export class GameService {
  private active=new Map<string,Session>();private timer?:ReturnType<typeof setTimeout>;private closed=false;private rates=new Map<string,{at:number;count:number}>();
  private epoch=Date.now();private monotonic=performance.now();now=()=>this.epoch+performance.now()-this.monotonic;
  online:(uid:string)=>boolean=()=>true;notify:(g:Session,directoryChanged:boolean,canvas?:CanvasEvent)=>Promise<void>=async()=>{};onError:(e:unknown)=>void=()=>{};
  constructor(private service:Service){}
  async initialize(){for(const row of await this.service.db.all("SELECT state FROM game_sessions WHERE status<>'finished'")){const g=JSON.parse(row.state) as Session;if(g.status==='playing'){const now=this.now();g.pauseStarted=g.pauseStarted?Math.min(g.pauseStarted,now):now;for(const seat of activeSeats(g)){if(seat.missingAt)seat.grace=Math.max(0,seat.grace-Math.max(0,now-seat.missingAt));seat.missingAt=now;}g.pausedUntil=Math.min(...activeSeats(g).map(s=>now+s.grace));g.revision++;await this.save(this.service.db,g);}this.active.set(g.id,g);}this.schedule();}
  close(){this.closed=true;clearTimeout(this.timer);this.active.clear();this.rates.clear();}
  private async requireVoice(tx:Connection,uid:string,channelId:string){const channel=await this.service.channel(tx,uid,channelId);if(channel.kind!=='voice'||!await tx.one('SELECT user_id FROM voice_members WHERE user_id=? AND channel_id=?',[uid,channelId]))fail(403,'VOICE_REQUIRED','Join this voice channel to play or watch.');return channel;}
  private async allowed(tx:Connection,uid:string,g:Session){const m=await tx.one('SELECT m.user_id FROM members m JOIN users u ON u.id=m.user_id JOIN servers s ON s.id=m.server_id WHERE m.user_id=? AND m.server_id=? AND u.banned=0 AND (u.guest=0 OR s.allow_guests=1)',[uid,g.serverId]);if(!m)fail(403,'FORBIDDEN','Join the game server to play or watch.');if(!g.seats.some(s=>s.id===uid&&!s.left))await this.requireVoice(tx,uid,g.channelId);}
  private async load(tx:Connection,id:string):Promise<Session>{const row=await tx.one('SELECT state FROM game_sessions WHERE id=?',[id]);if(!row)fail(404,'NOT_FOUND','Game not found.');return JSON.parse(row!.state);}
  private async save(tx:Connection,g:Session,roster=false){g.updatedAt=this.now();const state=JSON.stringify(g);if(Buffer.byteLength(state,'utf8')>768*1024)fail(413,'CAPACITY','This game has reached its drawing limit.');await tx.run('INSERT INTO game_sessions(id,server_id,channel_id,host_id,kind,status,updated_at,state) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET host_id=excluded.host_id,status=excluded.status,updated_at=excluded.updated_at,state=excluded.state',[g.id,g.serverId,g.channelId,g.hostId,g.kind,g.status,g.updatedAt,state]);if(roster){await tx.run('DELETE FROM game_players WHERE game_id=?',[g.id]);for(const seat of activeSeats(g))await tx.run('INSERT INTO game_players(game_id,user_id) VALUES(?,?)',[g.id,seat.id]);}}
  private summary(g:Session,uid:string):GameSummary{return {id:g.id,channelId:g.channelId,kind:g.kind,hostId:g.hostId,hostName:g.hostName,status:g.status,players:activeSeats(g).length,maxPlayers:g.settings.maxPlayers,minPlayers:definition(g.kind).min,paused:Boolean(g.pausedUntil),seated:g.seats.some(s=>s.id===uid&&!s.left)};}
  private joinable(g:Session){return g.status==='waiting'||(g.status==='playing'&&g.kind==='poker'&&g.state?.phase==='between');}
  async list(uid:string,channelId:string){await this.requireVoice(this.service.db,uid,channelId);const rows=await this.service.db.all("SELECT state FROM game_sessions WHERE channel_id=? AND status<>'finished' ORDER BY updated_at DESC LIMIT 60",[channelId]);return rows.map(r=>this.summary(JSON.parse(r.state),uid));}
  async get(uid:string,id:string):Promise<GameView>{await this.tickId(id);return this.service.db.transaction(async tx=>{const g=await this.load(tx,id);await this.allowed(tx,uid,g);const self=g.seats.findIndex(s=>s.id===uid&&!s.left),inVoice=Boolean(await tx.one('SELECT user_id FROM voice_members WHERE user_id=? AND channel_id=?',[uid,g.channelId]));return {...this.summary(g,uid),revision:g.revision,seats:g.seats,settings:g.settings,self,canPlay:self<0&&inVoice&&!g.pausedUntil&&this.joinable(g)&&activeSeats(g).length<g.settings.maxPlayers,canStart:g.status==='waiting'&&uid===g.hostId&&inVoice&&!g.pausedUntil&&activeSeats(g).length>=definition(g.kind).min,deadline:g.status==='waiting'?g.createdAt+600000:g.state?.deadline||0,serverNow:this.now(),pausedUntil:g.pausedUntil,result:g.result,state:g.state?project(g.kind,g.state,self):{phase:'lobby'}};});}
  private async free(tx:Connection,uid:string,except=''){if(await arcadeBusy(tx,uid,except)||await tx.one("SELECT id FROM chess_games WHERE status<>'finished' AND (white_id=? OR black_id=?)",[uid,uid]))fail(409,'CAPACITY','Finish or leave your existing game first.');}
  async create(uid:string,b:z.infer<typeof gameCreate>){const result=await this.service.mutate(uid,b.requestId,'game.create',b,async tx=>{const channel=await this.requireVoice(tx,uid,b.channelId);await this.free(tx,uid);const total=await tx.one("SELECT (SELECT COUNT(*) FROM game_sessions WHERE status<>'finished')+(SELECT COUNT(*) FROM chess_games WHERE status<>'finished') AS n");if(Number(total!.n)>=60)fail(409,'CAPACITY','The game limit is reached. Try again later.');const user=await tx.one('SELECT display_name FROM users WHERE id=?',[uid]),now=this.now();const g:Session={id:randomUUID(),serverId:channel.server_id,channelId:b.channelId,hostId:uid,hostName:user!.display_name,kind:b.kind,settings:b.settings,seats:[{id:uid,name:user!.display_name,left:false,grace:30000,missingAt:0}],status:'waiting',revision:1,createdAt:now,updatedAt:now,pausedUntil:0,pauseStarted:0,result:null,state:null};await tx.run("DELETE FROM game_sessions WHERE id IN (SELECT id FROM game_sessions WHERE status='finished' ORDER BY updated_at DESC LIMIT 10000 OFFSET 99)");await this.save(tx,g,true);return {id:g.id};});await this.changed(result.id);await this.reconcileVoice();return this.get(uid,result.id);}
  async command(uid:string,id:string,b:z.infer<typeof gameCommand>){
    const now=this.now(),rate=this.rates.get(uid);if(!rate||now-rate.at>1000)this.rates.set(uid,{at:now,count:1});else if(++rate.count>20)fail(429,'RATE_LIMIT','Slow down a little.');
    await this.tickId(id);
    const result=await this.service.mutate(uid,b.requestId,'game.command',{id,...b},async tx=>{
      const g=await this.load(tx,id);await this.allowed(tx,uid,g);if(g.status==='finished')fail(409,'GAME_FINISHED','This game has ended.');
      const concurrent=(g.kind==='drawing'||g.kind==='telephone')&&b.kind==='action'&&b.action?.token===g.state?.token;
      if(g.revision!==b.revision&&!concurrent)fail(409,'STALE_GAME','The game changed. Review the latest state.');
      let roster=false;let seat=g.seats.findIndex(s=>s.id===uid&&!s.left);
      if(!['leave','close'].includes(b.kind))await this.requireVoice(tx,uid,g.channelId);
      if(b.kind==='join'){
        if(seat>=0)fail(409,'SEAT_TAKEN','You already have a seat.');if(!this.joinable(g)||g.pausedUntil||activeSeats(g).length>=g.settings.maxPlayers)fail(409,'SEAT_TAKEN','Seats are unavailable now. You can keep watching.');await this.free(tx,uid,id);
        for(const p of activeSeats(g))if(await tx.one('SELECT user_id FROM user_blocks WHERE (user_id=? AND blocked_id=?) OR (user_id=? AND blocked_id=?)',[uid,p.id,p.id,uid]))fail(403,'FORBIDDEN','This game is unavailable.');
        const user=await tx.one('SELECT display_name FROM users WHERE id=?',[uid]);seat=g.seats.findIndex(s=>s.left);if(seat<0)seat=g.seats.length;g.seats[seat]={id:uid,name:user!.display_name,left:false,grace:30000,missingAt:0};if(g.state){pokerJoin(g.state,g.settings,seat);g.state.active[seat]=true;}roster=true;
      }else{
        if(seat<0)fail(403,'FORBIDDEN','Spectators cannot change a game.');
        if(b.kind==='close'){if(g.hostId!==uid||g.status!=='waiting')fail(403,'FORBIDDEN','Only the host can close the waiting game.');g.status='finished';g.result='Lobby closed';}
        else if(b.kind==='leave'){this.remove(g,seat,this.now());this.reconcilePause(g,this.now());roster=true;}
        else if(b.kind==='start'){
          if(g.hostId!==uid||g.status!=='waiting'||g.pausedUntil||activeSeats(g).length<definition(g.kind).min)fail(409,'NOT_READY','Wait for enough players to join.');
          for(const p of activeSeats(g))await this.requireVoice(tx,p.id,g.channelId);
          g.seats=g.seats.filter(s=>!s.left);g.state=startEngine(g.kind,g.seats.length,g.settings,this.now());g.status='playing';roster=true;
        }else{
          if(g.status!=='playing'||g.pausedUntil)fail(409,'PAUSED','Wait for the players to return to voice.');
          if(b.action?.type==='next'&&uid!==g.hostId)fail(403,'FORBIDDEN','Only the host can start the next round.');
          try{act(g.kind,g.state!,seat,b.action,g.settings,this.now());}catch(e){fail(400,'INVALID_MOVE',e instanceof Error?e.message:'That action is unavailable.');}
          this.complete(g);
        }
      }
      g.revision++;await this.save(tx,g,roster);const canvas:CanvasEvent|undefined=b.kind==='action'&&b.action&&['stroke','clear'].includes(b.action.type)?{id,revision:g.revision,serverNow:this.now(),token:b.action.token!,seat,requestId:b.requestId,type:b.action.type as 'stroke'|'clear',...(b.action.stroke?{stroke:b.action.stroke}:{})}:undefined;return {id,...(canvas?{canvas}:{})};
    });await this.changed(result.id,result.canvas);if(b.kind==='join'||b.kind==='start')await this.reconcileVoice();return b.kind==='leave'?{left:true,id}:this.get(uid,result.id);
  }
  private complete(g:Session){if(g.state?.result){g.status='finished';g.result=g.state.result;g.pausedUntil=0;}}
  private remove(g:Session,seat:number,now:number){const person=g.seats[seat];person.left=true;person.missingAt=0;if(g.state){const previous=g.state.deadline;depart(g.kind,g.state,seat,g.settings,now);if(g.pauseStarted&&g.state.deadline!==previous)g.pauseStarted=now;}this.complete(g);const remaining=activeSeats(g);if(!remaining.length){g.status='finished';g.result='Game closed';g.pausedUntil=0;}else if(person.id===g.hostId){const host=remaining.find(s=>!s.missingAt)||remaining[0];g.hostId=host.id;g.hostName=host.name;}}
  private reconcilePause(g:Session,now:number){const absent=activeSeats(g).filter(s=>s.missingAt);g.pausedUntil=absent.length?Math.min(...absent.map(s=>s.missingAt+s.grace)):0;if(!g.pausedUntil&&g.pauseStarted){const elapsed=now-g.pauseStarted;if(g.state?.deadline)g.state.deadline+=elapsed;if(g.state?.started)g.state.started+=elapsed;g.pauseStarted=0;}else if(g.pausedUntil&&!g.pauseStarted)g.pauseStarted=now;}
  async reconcileVoice(){if(!this.active.size)return;const voice=new Map((await this.service.db.all('SELECT user_id,channel_id FROM voice_members')).map(r=>[r.user_id,r.channel_id]));
    for(const cached of [...this.active.values()]){await this.tickId(cached.id);const g=this.active.get(cached.id);if(!g)continue;if(activeSeats(g).some(s=>(voice.get(s.id)===g.channelId&&this.online(s.id))===Boolean(s.missingAt))){
      await this.service.db.transaction(async tx=>{const row=await tx.one('SELECT state FROM game_sessions WHERE id=?',[g.id]);if(!row)return;const current=JSON.parse(row.state) as Session;if(current.status==='finished')return;const now=this.now();for(const s of activeSeats(current)){const present=voice.get(s.id)===current.channelId&&this.online(s.id);if(present&&s.missingAt){s.grace=Math.max(0,s.grace-(now-s.missingAt));s.missingAt=0;}else if(!present&&!s.missingAt)s.missingAt=now;}this.reconcilePause(current,now);current.revision++;await this.save(tx,current);});await this.changed(g.id);
    }}
  }
  private deadline(g:Session){return g.status==='waiting'?Math.min(g.createdAt+600000,g.pausedUntil||Infinity):g.pausedUntil||g.state?.deadline||g.updatedAt+7200000;}
  private async changed(id:string,canvas?:CanvasEvent){if(this.closed)return;const row=await this.service.db.one('SELECT state FROM game_sessions WHERE id=?',[id]);if(!row){const removed=this.active.get(id);this.active.delete(id);if(removed)await this.notify({...removed,status:'finished'},true).catch(this.onError);this.schedule();return;}const g=JSON.parse(row.state) as Session,previous=this.active.get(id);const directoryChanged=!previous||g.status!==previous.status||g.hostId!==previous.hostId||activeSeats(g).map(s=>s.id).join()!==activeSeats(previous).map(s=>s.id).join()||Boolean(g.pausedUntil)!==Boolean(previous.pausedUntil)||(g.kind==='poker'&&(g.state?.phase==='between')!==(previous.state?.phase==='between'));if(g.status==='finished')this.active.delete(id);else this.active.set(id,g);await this.notify(g,directoryChanged,canvas).catch(this.onError);this.schedule();}
  private schedule(){clearTimeout(this.timer);if(this.closed||!this.active.size)return;const nearest=Math.min(...[...this.active.values()].map(g=>this.deadline(g)));this.timer=setTimeout(()=>{void this.tick().catch(e=>{this.onError(e);if(!this.closed){this.timer=setTimeout(()=>this.schedule(),1000);this.timer.unref();}});},Math.max(1,Math.min(2147483647,nearest-this.now())));this.timer.unref();}
  private async tickId(id:string){const cached=this.active.get(id);if(!cached||this.deadline(cached)>this.now())return;const changed=await this.service.db.transaction(async tx=>{const row=await tx.one('SELECT state FROM game_sessions WHERE id=?',[id]);if(!row)return true;const g=JSON.parse(row.state) as Session,now=this.now();if(g.status==='finished'||this.deadline(g)>now)return false;let roster=false;
      if(g.status==='waiting'&&now>=g.createdAt+600000){g.status='finished';g.result='Lobby expired';}
      else if(g.pausedUntil){for(let i=0;i<g.seats.length;i++){const s=g.seats[i];if(!s.left&&s.missingAt&&now>=s.missingAt+s.grace){this.remove(g,i,now);roster=true;}}this.reconcilePause(g,now);}
      else if(g.state){timeout(g.kind,g.state,g.settings,now);this.complete(g);}
      g.revision++;await this.save(tx,g,roster);return true;});if(changed)await this.changed(id);}
  async tick(){for(const id of [...this.active.keys()])await this.tickId(id);this.schedule();}
}
